 "content": "from collections import Counter, deque


def transform(grid):
    """Repair isolated pixels using the dominant surrounding region."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    small = set()
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(comp) <= 2:
                small.update(comp)

    # A diagonal pair of corrupted cells can complete a 2x2 block whose
    # other two corners agree; restore the matching block color.
    for r in range(h - 1):
        for c in range(w - 1):
            for a, b, u, v in (( (r,c), (r+1,c+1), (r,c+1), (r+1,c) ),
                               ( (r,c+1), (r+1,c), (r,c), (r+1,c+1) )):
                if a in small and b in small and grid[a[0]][a[1]] == grid[b[0]][b[1]]:
                    if grid[u[0]][u[1]] == grid[v[0]][v[1]]:
                        fill = grid[u[0]][u[1]]
                        out[a[0]][a[1]] = fill
                        out[b[0]][b[1]] = fill

    for r, c in small:
        if out[r][c] != grid[r][c]:
            continue
        neighbors = []
        for y in range(max(0, r - 1), min(h, r + 2)):
            for x in range(max(0, c - 1), min(w, c + 2)):
                if (y, x) != (r, c):
                    neighbors.append(grid[y][x])
        if neighbors:
            counts = Counter(neighbors)
            best_count = max(counts.values())
            candidates = [v for v, n in counts.items() if n == best_count]
            # In ties prefer a cardinal neighbor, then the first seen value.
            if len(candidates) > 1:
                for dy, dx in ((-1, 0), (0, -1), (0, 1), (1, 0)):
                    y, x = r + dy, c + dx
                    if 0 <= y < h and 0 <= x < w and grid[y][x] in candidates:
                        out[r][c] = grid[y][x]
                        break
                else:
                    out[r][c] = candidates[0]
            else:
                out[r][c] = candidates[0]
    return out


